app.addEventListener('click', (event) => { const target = event.target.closest('[data-action]'); if (!target || target.disabled) return; if (target.dataset.action === 'open-date-picker') { state.dateDraft = state.dob || ''; state.sheet = 'dob'; render(); } if (target.dataset.action === 'date-confirm') { state.dob = state.dateDraft || ''; state.dateDraft = ''; state.basicError = ''; state.sheet = null; render(); } if (target.dataset.action === 'open-country-picker') { state.sheet = 'country'; render(); } if (target.dataset.action === 'country-choice') { state.countryCode = target.dataset.country; state.sheet = null; render(); } });

let swipeStart = null;
app.addEventListener('pointerdown', (event) => { const surface = event.target.closest('.discover-screen, .create-screen'); if (surface) swipeStart = { x: event.clientX, tabs: surface.classList.contains('discover-screen') ? 'discover' : 'create' }; });
app.addEventListener('pointerup', (event) => { if (!swipeStart) return; const delta = event.clientX - swipeStart.x; if (Math.abs(delta) > 55) { if (swipeStart.tabs === 'discover') { const views = ['poster', 'map', 'plans']; let index = views.indexOf(state.discoverView) + (delta < 0 ? 1 : -1); index = Math.max(0, Math.min(views.length - 1, index)); state.discoverView = views[index]; render(); } if (swipeStart.tabs === 'create') { state.createTab = state.createTab === 'new' ? 'posts' : 'new'; render(); } } swipeStart = null; });

app.addEventListener('click', (event) => { const target = event.target.closest('[data-action="map-filter"]'); if (!target) return; state.filter = target.dataset.filter; state.feedState = 'loaded'; render(); notify(`${state.filter} applied to this map area.`); });

const renderExistingSheet = renderSheet;
renderSheet = function renderSheetWithCountryPicker() { if (state.sheet === 'dob') return ''; if (state.sheet === 'country') return `<div class="sheet-backdrop"><section class="sheet country-picker-sheet" role="dialog" aria-modal="true" aria-labelledby="country-picker-title"><div class="sheet-title-row"><h2 id="country-picker-title">Choose a country code</h2><button class="icon-button" data-action="close-sheet" aria-label="Close country code picker">${icon('cancel')}</button></div><p>Choose the number format for your phone.</p>${['+61','+1','+44'].map((country) => `<button class="option ${state.countryCode === country ? 'active' : ''}" data-action="country-choice" data-country="${country}"><span>${country}</span><i class="iconoir-check check"></i></button>`).join('')}</section></div>`; return renderExistingSheet(); };

